const seen = new Map<string, number>();
return occurrences.reduce((diagnostics, occurrence) => {
  const { id } = occurrence;
  if (seen.has(id)) {
    diagnostics.push({ code: 'OARC-E011', file: occurrence.file, id });
  } else {
    seen.set(id, occurrences.indexOf(occurrence));
  }
  return diagnostics;
}, [] as Diagnostic[]);
